import {CATEGORIES,PENDING,norm,number,dateValue,validity,aggregateLots,stockMetrics,movementsByDay,movementDelta,topRequested,filterLots} from './data.js';
const boot=window.SISTFARMA,client=boot.mode==='cliente',$=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>Number(v).toLocaleString('pt-BR',{maximumFractionDigits:2});
const icons={bell:'M6 8a6 6 0 0 1 12 0v6l3 3H3l3-3V8M10 21h4',menu:'M3 6h18M3 12h18M3 18h18',search:'m21 21-4.4-4.4M19 10.5a8.5 8.5 0 1 1-17 0 8.5 8.5 0 0 1 17 0',refresh:'M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-2l2 3M4 16l2 3a7 7 0 0 0 12-2',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',box:'m3 7 9-5 9 5-9 5-9-5v10l9 5 9-5V7M12 12v10M7 4.8l9 5',orders:'M7 3h10v3H7zM7 4H4v18h16V4h-3M8 11h8M8 16h6',calendar:'M4 5h16v16H4zM4 10h16M8 2v6M16 2v6M8 14h3M14 14h2',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6zM12 8v8M8 12h8',check:'M8 3h8v4H8zM8 5H4v17h16V5h-4M8 14l3 3 5-6',chart:'M4 20V12h4v8M10 20V4h4v16M16 20V8h4v12',users:'M8 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8M1 22v-3a7 7 0 0 1 14 0v3M17 4a4 4 0 0 1 0 8M18 15a5 5 0 0 1 5 5v2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M10 2h4l1 3 3 1 3 1-2 4 1 3 1 3-4 2-2 3h-4l-1-3-3-1-3-1 2-4-1-3-1-3 4-2z',warning:'m12 2 11 19H1zM12 8v6M12 17v1',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M12 6v6l4 2',cart:'M2 3h3l3 13h11l3-9H6M9 21h1M18 21h1',pill:'m8 16 8-8M6 18a5.6 5.6 0 0 1 0-8l4-4a5.6 5.6 0 0 1 8 8l-4 4a5.6 5.6 0 0 1-8 0',plus:'M12 4v16M4 12h16',arrow:'M4 12h16m-6-6 6 6-6 6',print:'M6 9V2h12v7M6 17H2V9h20v8h-4M6 14h12v8H6z',exit:'M9 3H3v18h6M9 12h12m-5-5 5 5-5 5'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.box}"/></svg>`}
const S={config:null,user:null,area:client?'catalog':'dashboard',q:'',category:'',filter:'all',orderFilter:'PENDENTES',reportFrom:'',reportTo:'',lots:null,locations:null,awaiting:null,orders:null,moves:null,conferences:null,external:null,audit:null,users:null,conferenceHistory:null,deleted:null,errors:{},selected:new Set(),cart:[],lastReceipt:null,busy:false,generation:0,connected:false,lastUpdated:null};
const titles={dashboard:['Visão geral','Acompanhe a situação atual da farmácia.'],stock:['Estoque disponível','Medicamentos e materiais liberados para uso.'],awaiting:['Aguardando conferência / SISCOFIS','Produtos recebidos e bloqueados para uso até a liberação.'],orders:['Pedidos','Acompanhe a separação e a entrega das solicitações.'],validities:['Lotes / Validades','Priorize os lotes que precisam de atenção.'],controlled:['Medicamentos Controlados','Estoque e validades dos medicamentos controlados.'],external:['Externos','Materiais e medicamentos externos à farmácia.'],conference:['Conferência física','Verificação semanal dos lotes selecionados.'],audit:['Auditoria','Histórico de ações realizadas no sistema.'],users:['Usuários','Gerencie o acesso dos administradores.'],reports:['Relatórios','Consulte e imprima as movimentações do estoque.'],settings:['Configurações','Conexão e preferências do aplicativo.'],catalog:['Solicitar produtos','Pesquise os produtos e monte sua solicitação.'],receipt:['Comprovante','Confira o resultado da última solicitação.']};
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.classList.toggle('error',error);el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,error?9000:4500)}
async function api(path,method='GET',body){
 let response;try{response=await fetch('/api'+path,{method,headers:{'X-Sistfarma-Key':boot.key,...(body!==undefined?{'Content-Type':'application/json'}:{})},body:body!==undefined?JSON.stringify(body):undefined});}catch(_){throw Error('O aplicativo local foi encerrado. Abra-o novamente pelo atalho.')}
 const data=await response.json();if(!response.ok){const err=Error((response.status===404&&(/^(\/recebimentos|\/itens-localizados|\/localizadores|\/pedidos\/\d+\/localizadores)/.test(path))?'Atualize o servidor com o módulo Localizador / SISCOFIS 1.4.3 para usar esta função. Nenhum produto foi enviado ao estoque.':data.erro)||`Erro ${response.status} ao consultar o servidor.`);err.status=response.status;err.uncertain=data.resultado_incerto;if(response.status===401&&path!=='/login'){S.user=null;clearData();}throw err}return data;
}
function clearData(){S.generation++;for(const k of ['lots','locations','awaiting','orders','moves','conferences','external','audit','users','conferenceHistory','deleted'])S[k]=null;S.errors={};S.selected.clear();S.lastUpdated=null;S.q='';S.filter='all';S.category=''}
function badge(text,tone='neutral'){return `<span class="badge ${tone}">${esc(text)}</span>`}
function validityBadge(value){const v=validity(value);return badge(v.label,v.tone)}
function statusBadge(status){const labels={NOVO:'Novo',EM_SEPARACAO:'Em separação',PRONTO:'Pronto',ENTREGUE:'Entregue',CANCELADO:'Cancelado',CANCELADO_SEM_ESTOQUE:'Sem estoque',ATENDIDO:'Atendido',PENDENTE:'Pendente',OK:'Lote OK',DIVERGENTE:'Divergente',AJUSTADO:'Ajustado'};return badge(labels[status]||status||'—',({NOVO:'warning',EM_SEPARACAO:'blue',PRONTO:'purple',ENTREGUE:'success',CANCELADO:'danger',CANCELADO_SEM_ESTOQUE:'danger',ATENDIDO:'success',PENDENTE:'warning',OK:'success',DIVERGENTE:'danger',AJUSTADO:'blue'})[status]||'neutral')}
function empty(message='Nenhum registro encontrado.'){return `<div class="empty">${esc(message)}</div>`}
function unavailable(key){return `<div class="empty"><strong>Não foi possível carregar os dados</strong>${esc(S.errors[key]||'Atualize para tentar novamente.')}</div>`}
function table(headers,rows,compact=false){if(!rows.length)return empty();return `<div class="table-wrap"><table class="${compact?'compact':''}"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function panel(title,body,action=''){return `<section class="panel"><div class="panel-heading"><h2>${title}</h2>${action}</div>${body}</section>`}
function navButton(area,label='Ver todos',filter=''){return `<button class="panel-link" data-nav="${area}" ${filter?`data-filter="${filter}"`:''}>${label} →</button>`}
function renderMenu(){const items=client?[['catalog','Solicitar produtos','cart'],['receipt','Comprovante','orders'],['settings','Configurações','settings']]:[['dashboard','Painel','grid'],['stock','Estoque','box'],['awaiting','Aguardando conferência / SISCOFIS','clock'],['orders','Pedidos','orders'],['validities','Lotes / Validades','calendar'],['controlled','Medicamentos Controlados','shield'],['external','Externos','box'],['conference','Conferência','check'],['audit','Auditoria','chart'],['users','Usuários','users'],['reports','Relatórios','orders'],['settings','Configurações','settings']];$('#menu').innerHTML=items.map(([area,label,i])=>{const restricted=['audit','users'].includes(area)&&S.user?.perfil!=='gerente';return `<button class="nav-item ${S.area===area?'active':''}" data-nav="${area}" ${restricted?'disabled title="Acesso exclusivo ao Gerente"':''}>${icon(i)}<span>${label}</span>${restricted?'<small>Gerente</small>':''}</button>`}).join('');$('#appName').textContent=client?'Cliente Farmácia':'Gestor Farmácia';$('#version').textContent='Versão '+boot.version;$('#profileName').textContent=S.user?.nome||S.user?.usuario||(client?'Solicitação de produtos':'Acesso à farmácia');$('#profileRole').textContent=S.user?S.user.perfil==='gerente'?'Gerente':'Administrador':'Rede local';$('#avatar').textContent=(S.user?.nome||'SF').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();$('#logout').hidden=!S.user;$('#notifications').hidden=client||!S.user;$('#notifications').innerHTML=icon('bell')+(S.orders?`<span class="notification-count">${S.orders.filter(p=>PENDING.includes(p.status)).length}</span>`:'');}
function updateHeader(){renderMenu();const [title,sub]=titles[S.area];$('#areaTitle').textContent=title;$('#subtitle').textContent=sub;$('#serverAddress').textContent=(S.config?.servidor_url||'').replace(/^https?:\/\//,'');$('#lastUpdate').textContent=S.lastUpdated?'Dados consultados às '+S.lastUpdated.toLocaleTimeString('pt-BR'):'Aguardando atualização';}
function connection(ok){S.connected=ok;$('#connectionText').textContent=ok?'Conectado ao servidor':'Servidor indisponível';$('#connectionDot').className='dot '+(ok?'':'danger')}
async function ping(){try{await api('/ping');connection(true)}catch(_){connection(false)}}
function renderNotices(){const entries=Object.entries(S.errors);$('#notices').innerHTML=entries.length?`<div class="notice error"><strong>Consulta incompleta.</strong> ${entries.map(([k,v])=>esc(({lots:'Estoque',locations:'Localizadores',awaiting:'Aguardando conferência / SISCOFIS',orders:'Pedidos',moves:'Movimentações',conferences:'Conferência',external:'Externos',audit:'Auditoria',users:'Usuários',conferenceHistory:'Histórico de conferências',deleted:'Lotes excluídos'})[k]||k)+': '+esc(v)).join(' ')} <button class="text-button" data-action="refresh">Tentar novamente</button></div>`:'';}
async function fetchResource(key,path,field){try{const data=await api(path);const list=Array.isArray(data)?data:data[field];if(!Array.isArray(list))throw Error('O servidor retornou um formato inesperado.');if(key==='external')return list.map((r,i)=>({...r,id:r.id??i+1,material:r.material??r.Material,lote:r.lote??r.Lote,validade:r.validade??r.Validade,estoque_inicial:r.estoque_inicial??r['Estoque Inicial'],estoque_atual:r.estoque_atual??r['Estoque Atual'],observacao:r.observacao??r['Observação']}));if(key==='deleted')return list.map(r=>({...r,excluido_em:r.excluido_em??r['Data Exclusão'],medicamento:r.medicamento??r.Medicamento,ficha:r.ficha??r.Ficha,motivo:r.motivo??r.Motivo,excluido_por:r.excluido_por??'—'}));return list}catch(e){throw e}}
async function refresh(){if(S.busy)return;S.busy=true;const generation=S.generation;$('#refreshTop').disabled=true;$('#refreshTop').title='Atualizando…';
 try{await ping();if(!client&&!S.user){render();return}const tasks={lots:async()=>{const data=await Promise.all(CATEGORIES.map(async categoria=>(await fetchResource('lots','/lotes?categoria='+encodeURIComponent(categoria),'lotes')).map(l=>({...l,categoria:l.categoria||categoria}))));return data.flat()}};
 if(!client)Object.assign(tasks,{orders:()=>fetchResource('orders','/pedidos','pedidos'),moves:()=>fetchResource('moves','/historico','registros'),conferences:()=>fetchResource('conferences','/conferencias/semana','conferencias'),locations:()=>fetchResource('locations','/localizadores','localizadores')});
 const names=Object.keys(tasks),results=await Promise.allSettled(names.map(k=>tasks[k]()));if(generation!==S.generation)return;results.forEach((r,i)=>{const k=names[i];if(r.status==='fulfilled'){S[k]=r.value;delete S.errors[k]}else{S[k]=null;S.errors[k]=r.reason.message}});if(S.lots&&S.locations){const locator=new Map(S.locations.map(l=>[l.id,l.localizador]));S.lots=S.lots.map(l=>({...l,localizador:locator.get(l.id)||''}))}S.lastUpdated=results.every(r=>r.status==='fulfilled')?new Date():null;render();
 if(['awaiting','external','audit','users'].includes(S.area))await loadArea(S.area);
 }finally{S.busy=false;$('#refreshTop').disabled=false;$('#refreshTop').title='Atualizar dados';if(!client&&!S.user)render();}}
async function loadArea(area){const map={awaiting:['awaiting','/recebimentos','recebimentos'],external:['external','/apoio','itens'],audit:['audit','/auditoria?limite=1000','registros'],users:['users','/usuarios','usuarios']};if(!map[area])return;const [key,path,field]=map[area],generation=S.generation;try{const data=await fetchResource(key,path,field);if(generation!==S.generation)return;S[key]=data;delete S.errors[key]}catch(e){if(generation!==S.generation)return;S[key]=null;S.errors[key]=e.message}if(S.area===area)render();}
function navigate(area,filter){if(!titles[area])return;if(['audit','users'].includes(area)&&S.user?.perfil!=='gerente')return;S.area=area;S.q='';$('#globalSearch').value='';S.category='';S.filter=filter||(area==='validities'?'due':'all');S.orderFilter=filter==='all'?'TODOS':'PENDENTES';S.selected.clear();render();if(client||S.user)loadArea(area);}
function render(){updateHeader();renderNotices();if(!client&&!S.user&&S.area!=='settings'){renderLogin();return}if(S.user?.trocar_senha){renderPassword();return}const renderers={dashboard:renderDashboard,stock:renderStock,awaiting:renderAwaiting,validities:renderStock,controlled:renderStock,orders:renderOrders,external:renderExternal,conference:renderConference,audit:renderAudit,users:renderUsers,reports:renderReports,settings:renderSettings,catalog:renderCatalog,receipt:renderReceipt};renderers[S.area]();}
function renderLogin(){ $('#notices').innerHTML='';$('#content').innerHTML=`<section class="panel login-card"><h2>Bem-vindo ao SISTFARMA</h2><p>Entre com a conta que você já utiliza na farmácia.</p><form id="loginForm"><label class="field">Usuário<input name="usuario" required autocomplete="username" autofocus></label><label class="field">Senha<input name="senha" type="password" required autocomplete="current-password"></label><div class="error-text" id="loginError" role="alert"></div><button class="button" type="submit">Entrar no Gestor ${icon('arrow')}</button></form><div class="actions"><button class="text-button" data-nav="settings">Configurar servidor</button></div></section>`;
 $('#loginForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;$('#loginError').textContent='';try{const result=await api('/login','POST',Object.fromEntries(new FormData(e.target)));clearData();S.user=result.usuario;connection(true);render();if(!S.user.trocar_senha)await refresh()}catch(error){$('#loginError').textContent=error.message}finally{b.disabled=false}};}
function renderPassword(){ $('#content').innerHTML=`<section class="panel login-card"><h2>Defina sua nova senha</h2><p>Sua conta precisa de uma senha pessoal antes de continuar.</p><form id="passwordForm"><label class="field">Nova senha<input type="password" name="nova_senha" required minlength="6" autocomplete="new-password"></label><label class="field">Confirme a senha<input type="password" name="confirmacao" required minlength="6" autocomplete="new-password"></label><div class="error-text" id="passwordError"></div><button class="button">Salvar senha</button></form></section>`;$('#passwordForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(d.nova_senha!==d.confirmacao){$('#passwordError').textContent='As senhas são diferentes.';return}const b=e.target.querySelector('button');b.disabled=true;try{await api('/minha-senha','POST',{nova_senha:d.nova_senha});S.user.trocar_senha=false;await refresh()}catch(err){$('#passwordError').textContent=err.message}finally{b.disabled=false}};}
function renderDashboard(){const metrics=S.lots===null?null:stockMetrics(S.lots),pending=S.orders?.filter(x=>PENDING.includes(x.status)),confs=S.conferences?.filter(x=>x.resultado==='PENDENTE');
 const cardData=[['Itens em estoque',metrics?.items,metrics?`${metrics.stockedLots} lotes com saldo`:'Consulta indisponível','box','', 'stock','positive'],['Validades ≤ 90 dias',metrics?.bins.critical,'Lotes com saldo, incluindo vencidos','warning','red','validities','critical'],['Entre 91 e 120 dias',metrics?.bins.attention,'Lotes que merecem atenção','clock','amber','validities','attention'],['Pedidos pendentes',pending?.length,confs?`${confs.length} conferências pendentes`:'Conferência indisponível','cart','blue','orders',''],['Itens sem estoque',metrics?.zero,'Produtos com saldo total zerado','pill','purple','stock','zero']];
 let html=`<div class="cards">${cardData.map(([label,value,sub,i,color,area,filter])=>`<button class="metric" data-nav="${area}" data-filter="${filter}"><span class="metric-icon ${color}">${icon(i)}</span><span class="metric-arrow">↗</span><span class="metric-label">${label}</span><strong class="metric-value">${value===undefined?'—':fmt(value)}</strong><small>${sub}</small></button>`).join('')}</div><div class="dashboard-grid">`;
 html+=panel('Situação das validades',metrics?donut(metrics):unavailable('lots'),navButton('validities','Ver detalhes'));
 html+=panel('Movimentações · últimos 7 dias',S.moves===null?unavailable('moves'):lineChart(movementsByDay(S.moves)),navButton('reports','Ver'));
 html+=panel('Top 5 mais solicitados',S.orders===null?unavailable('orders'):rankChart(topRequested(S.orders)),`<span class="subtle">Últimos 30 dias</span>`);
 html+=panel('Pedidos recentes',S.orders===null?unavailable('orders'):table(['Pedido','Solicitante','Situação'],S.orders.slice(0,5).map(p=>[`<button class="row-link" data-order="${p.id}">#${p.id}</button><span class="secondary">${esc(p.data)}</span>`,esc(p.solicitante||p.nome),statusBadge(p.status)]),true),navButton('orders','Ver todos','all'));
 const zeros=metrics?aggregateLots(S.lots).filter(x=>x.estoque_total<=0):[];
 html+=panel('Estoque crítico',metrics?table(['Item','Saldo'],zeros.slice(0,5).map(x=>[`<button class="row-link" data-find="${esc(x.medicamento)}">${esc(x.medicamento)}</button><span class="secondary">${esc(x.categoria)}</span>`,badge('Sem estoque','danger')]),true):unavailable('lots'),navButton('stock','Ver todos','zero'));
 html+=panel('Últimas movimentações',S.moves===null?unavailable('moves'):table(['Movimento','Produto','Quantidade'],S.moves.slice(0,5).map(m=>{const delta=movementDelta(m);return [badge(delta>0?'Entrada':delta<0?'Saída':'Ajuste',delta>0?'success':delta<0?'danger':'neutral'),`<button class="row-link" data-find="${esc(m.medicamento)}">${esc(m.medicamento)}</button><span class="secondary">${esc(m.data)}</span>`,`<b class="${delta>0?'success-text':'danger-text'}">${delta>0?'+':''}${fmt(delta)}</b>`]}),true),navButton('reports','Ver todas'));
 $('#content').innerHTML=html+'</div>'+`<div class="conference-strip"><span>${icon('check')} <b>Conferência da semana</b> · ${confs===undefined?'Consulta indisponível':confs.length+' lotes pendentes'}</span>${navButton('conference','Conferir lotes')}</div>`;
}
function donut(metrics){const b=metrics.bins,total=Object.values(b).reduce((a,x)=>a+x,0),data=[['critical','≤ 90 dias','#d9655d'],['attention','91–120 dias','#e5b34b'],['regular','> 120 dias','#5b8950'],['unknown','Sem data','#c0c9bf']];let start=0;const gradient=data.map(([k,,color])=>{const end=start+(total?b[k]/total*100:0),s=`${color} ${start}% ${end}%`;start=end;return s}).join(',');return `<div class="donut-wrap"><div class="donut" style="background:${total?'conic-gradient('+gradient+')':'#edf0eb'}"><div class="donut-inner"><strong>${fmt(total)}</strong><small>lotes com saldo</small></div></div><div class="legend">${data.map(([k,label,c])=>`<button data-nav="validities" data-filter="${k}"><i class="swatch" style="background:${c}"></i>${label}<b>${fmt(b[k])}</b></button>`).join('')}</div></div><p class="subtle">As validades são calculadas por lote com estoque disponível.</p>`;}
function lineChart(rows){const max=Math.max(1,...rows.flatMap(r=>[r.entrada,r.saida])),x=i=>28+i*40,y=v=>126-v/max*102;const line=key=>rows.map((r,i)=>`${x(i)},${y(r[key])}`).join(' ');return `<div class="chart-key"><span><i class="swatch" style="background:#8caf60"></i>Entradas</span><span><i class="swatch" style="background:#315d3c"></i>Saídas</span></div><svg class="line-chart" viewBox="0 0 288 157" role="img" aria-label="Entradas e saídas registradas nos últimos sete dias">${[0,.5,1].map(n=>`<line x1="28" x2="270" y1="${y(n*max)}" y2="${y(n*max)}" stroke="#edf0ec"/><text x="1" y="${y(n*max)+3}">${fmt(n*max)}</text>`).join('')}<polyline points="${line('entrada')}" fill="none" stroke="#8caf60" stroke-width="2.5"/><polyline points="${line('saida')}" fill="none" stroke="#315d3c" stroke-width="2.5"/>${rows.map((r,i)=>`<circle cx="${x(i)}" cy="${y(r.saida)}" r="3" fill="#315d3c"><title>${r.label}: ${fmt(r.entrada)} entradas; ${fmt(r.saida)} saídas</title></circle><text x="${x(i)}" y="149" text-anchor="middle">${r.label}</text>`).join('')}</svg><p class="subtle">Movimentações registradas pelo servidor. Entradas incluem estornos e ajustes; cadastros antigos podem não constar no histórico.</p>`;}
function rankChart(rows){return rows.length?`<div class="rank-list">${rows.map(r=>`<button class="rank" data-find="${esc(r.name)}"><span title="${esc(r.name)}">${esc(r.name)}</span><div class="rank-bar"><i style="width:${r.value/Math.max(1,rows[0].value)*100}%"></i></div><b>${fmt(r.value)}</b></button>`).join('')}</div><p class="subtle" style="margin-top:18px">Quantidades solicitadas e atendidas. Itens e pedidos cancelados são excluídos.</p>`:empty('Nenhuma solicitação atendida no período.');}
function categorySelect(){return `<select id="categoryFilter" aria-label="Categoria"><option value="">Todas as categorias</option>${CATEGORIES.map(c=>`<option ${S.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select>`}
function stockFilter(){return `<select id="stockFilter" aria-label="Situação do estoque">${[['all','Todos os lotes'],['positive','Com estoque'],['zero','Itens sem estoque'],['due','Validade até 120 dias'],['critical','Até 90 dias / vencidos'],['attention','91 a 120 dias'],['regular','Acima de 120 dias'],['unknown','Sem data válida']].map(([v,label])=>`<option value="${v}" ${S.filter===v?'selected':''}>${label}</option>`).join('')}</select>`}
function currentLots(){return filterLots(S.lots||[],{query:S.q,category:S.area==='controlled'?'Medicamentos Controlados':S.category,filter:S.filter})}
function renderStock(){const rows=currentLots();$('#content').innerHTML=`<div class="toolbar"><input id="localSearch" type="search" placeholder="Pesquisar produto, lote ou localizador" value="${esc(S.q)}" aria-label="Pesquisar estoque">${S.area!=='controlled'?categorySelect():''}${stockFilter()}<button class="button" data-action="new-lot">${icon('plus')} Cadastrar lote</button><button class="button secondary" data-action="print-stock">${icon('print')} Imprimir</button></div><section class="panel"><div class="stats-line"><b>${rows.length} lotes</b><span>${S.selected.size} selecionados</span>${S.selected.size?'<button class="text-button danger-text" data-action="delete-selected">Excluir selecionados</button>':''}<button class="text-button" data-action="deleted-lots">Lotes excluídos</button></div>${S.lots===null?unavailable('lots'):table(['<input id="selectAll" type="checkbox" aria-label="Selecionar todos os lotes visíveis" '+(rows.length&&rows.every(r=>S.selected.has(r.id))?'checked':'')+'>','Produto / categoria','Ficha / lote','Localizador','Validade','Saldo','Cartela','Situação',''],rows.map(l=>[`<input type="checkbox" data-select-lot="${l.id}" aria-label="Selecionar ${esc(l.medicamento)} lote ${esc(l.ficha)}" ${S.selected.has(l.id)?'checked':''}>`,`<button class="row-link" data-lot="${l.id}">${esc(l.medicamento)}</button><span class="secondary">${esc(l.categoria)}</span>`,esc(l.ficha),`<b>${esc(l.localizador||'—')}</b>`,esc(l.validade||'—'),`<b>${fmt(l.estoque_atual)}</b>`,esc(l.comprimidos_cartela||'—'),validityBadge(l.validade),`<button class="button secondary small" data-lot="${l.id}">Editar</button>`]))}</section>`;}
function renderOrders(){let rows=S.orders||[];rows=rows.filter(p=>(S.orderFilter==='TODOS'||(S.orderFilter==='PENDENTES'?PENDING.includes(p.status):p.status===S.orderFilter))&&norm([p.id,p.solicitante,p.pg,p.om,p.data].join(' ')).includes(norm(S.q)));$('#content').innerHTML=`<div class="toolbar"><input id="localSearch" type="search" placeholder="Pesquisar pedido, nome ou OM" aria-label="Pesquisar pedidos" value="${esc(S.q)}"><select id="orderFilter" aria-label="Situação do pedido">${[['PENDENTES','Pendentes'],['TODOS','Todos'],['NOVO','Novos'],['EM_SEPARACAO','Em separação'],['PRONTO','Prontos'],['ENTREGUE','Entregues'],['CANCELADO','Cancelados']].map(([v,t])=>`<option value="${v}" ${S.orderFilter===v?'selected':''}>${t}</option>`).join('')}</select><button class="button secondary" data-action="refresh">Atualizar pedidos</button></div>${panel(`${rows.length} pedidos`,S.orders===null?unavailable('orders'):table(['Pedido','Data','Solicitante','OM','Itens','Situação',''],rows.map(p=>[`#${p.id}`,esc(p.data),esc([p.pg,p.solicitante||p.nome].filter(Boolean).join(' ')),esc(p.om),fmt(p.quantidade_itens??p.itens?.length??0),statusBadge(p.status),`<button class="button secondary small" data-order="${p.id}">Ver pedido</button>`])))}`;}

function currentAwaiting(){return (S.awaiting||[]).filter(l=>(!S.category||l.categoria===S.category)&&norm([l.medicamento,l.ficha,l.localizador,l.observacao].join(' ')).includes(norm(S.q)))}
function renderAwaiting(){const rows=currentAwaiting(),selected=rows.filter(l=>S.selected.has(l.id));$('#content').innerHTML=`<div class="notice"><strong>Indisponível para uso.</strong> Estas quantidades não compõem o estoque disponível e não podem ser solicitadas. Selecione os produtos autorizados e libere a quantidade desejada.</div><div class="toolbar"><input id="localSearch" type="search" aria-label="Pesquisar produtos em conferência" placeholder="Pesquisar produto, lote ou localizador" value="${esc(S.q)}">${categorySelect()}<button class="button" data-action="new-lot">${icon('plus')} Cadastrar recebimento</button><button class="button secondary" data-action="awaiting-history">Histórico de liberações</button><button class="button secondary" data-action="print-current">Imprimir lista</button></div><section class="panel"><div class="stats-line"><b>${rows.length} lotes aguardando</b><span>${selected.length} selecionados nesta lista</span><button class="button small" data-action="release-selected" ${!selected.length||S.awaiting===null?'disabled':''}>Liberar selecionados ao estoque</button></div>${S.awaiting===null?unavailable('awaiting'):table(['<input id="selectAllAwaiting" type="checkbox" aria-label="Selecionar todos os recebimentos visíveis" '+(rows.length&&selected.length===rows.length?'checked':'')+'>','Produto / categoria','Ficha / lote','Localizador','Validade','Aguardando','Já liberado','Registro',''],rows.map(l=>[`<input type="checkbox" data-select-awaiting="${l.id}" aria-label="Selecionar recebimento ${esc(l.medicamento)} lote ${esc(l.ficha)}" ${S.selected.has(l.id)?'checked':''}>`,`<strong>${esc(l.medicamento)}</strong><span class="secondary">${esc(l.categoria)}</span>${l.observacao?'<span class="secondary">'+esc(l.observacao)+'</span>':''}`,esc(l.ficha),`<b>${esc(l.localizador||'—')}</b>`,esc(l.validade||'—')+'<br>'+validityBadge(l.validade),`<b>${fmt(l.saldo_pendente)}</b><br>${badge('Bloqueado para uso','warning')}`,fmt(l.quantidade_liberada),esc(l.criado_em)+'<span class="secondary">'+esc(l.criado_por)+'</span>',`<div class="actions"><button class="button small" data-release-awaiting="${l.id}">Liberar</button><button class="button secondary small" data-edit-awaiting="${l.id}">Editar</button><button class="text-button danger-text" data-cancel-awaiting="${l.id}">Cancelar</button></div>`]))}</section>`;}
function releaseAwaiting(ids){const rows=currentAwaiting().filter(l=>ids.includes(l.id));if(!rows.length)throw Error('Selecione produtos na lista atual.');const operationId=crypto.randomUUID();formDialog('Liberar produtos para o estoque',`<p class="subtle">Confirme apenas as quantidades autorizadas. O restante continuará bloqueado em conferência / SISCOFIS.</p>${table(['Produto / lote','Aguardando','Quantidade a liberar'],rows.map(l=>[esc(l.medicamento)+'<span class="secondary">'+esc(l.ficha)+'</span>',fmt(l.saldo_pendente),`<input type="number" name="qty_${l.id}" aria-label="Quantidade a liberar de ${esc(l.medicamento)} lote ${esc(l.ficha)}" value="${l.saldo_pendente}" min="0.01" max="${l.saldo_pendente}" step="any" required>`]))}<label class="field">Referência da liberação (opcional)<input name="referencia" placeholder="Documento ou número de controle SISCOFIS"></label><label class="check"><input type="checkbox" required> Confirmo que estes produtos foram conferidos e autorizados para uso.</label>`,async d=>{const itens=rows.map(l=>({id:l.id,versao:l.versao,quantidade:numeric(d['qty_'+l.id],'Quantidade a liberar')}));if(itens.some(i=>i.quantidade<=0))throw Error('Informe uma quantidade maior que zero para cada item selecionado.');await api('/recebimentos/liberar','POST',{operacao_id:operationId,itens,referencia:d.referencia});S.selected.clear();await refresh();toast('Produtos liberados e enviados ao estoque disponível.');},'Confirmar liberação');}
function awaitingForm(id){const l=S.awaiting?.find(l=>l.id===id);if(!l)return;const operationId=crypto.randomUUID();formDialog('Editar recebimento em conferência',`<p class="subtle">Alterações afetam somente o saldo ainda bloqueado. Quantidades já liberadas permanecem no estoque.</p><div class="form-grid"><label class="field wide">Categoria<select name="categoria">${CATEGORIES.map(c=>`<option ${c===l.categoria?'selected':''}>${esc(c)}</option>`).join('')}</select></label>${field('Medicamento / material','medicamento',l.medicamento,'text','required')}${field('Ficha / lote','ficha',l.ficha,'text','required')}${field('Localizador','localizador',l.localizador||'','text','maxlength="120" placeholder="Ex.: Depósito A · Prateleira 03"')}${field('Validade','validade',isoDate(l.validade),'date')}${field('Quantidade ainda em conferência','saldo_pendente',l.saldo_pendente,'number','required min="0.01" step="any"')}${field('Comprimidos por cartela','comprimidos_cartela',l.comprimidos_cartela||'','number','min="1" step="1"')}<label class="field wide">Observação<textarea name="observacao">${esc(l.observacao)}</textarea></label></div>`,async d=>{await api('/recebimentos/'+id,'PUT',{...d,validade:brDate(d.validade),saldo_pendente:numeric(d.saldo_pendente,'Saldo pendente'),versao:l.versao,operacao_id:operationId});await loadArea('awaiting');toast('Recebimento atualizado; continua bloqueado.');});}
function cancelAwaiting(id){const l=S.awaiting?.find(l=>l.id===id);if(!l)return;const operationId=crypto.randomUUID();formDialog('Cancelar saldo em conferência',`<p>${esc(l.medicamento)} · ${esc(l.ficha)} · ${fmt(l.saldo_pendente)} unidades pendentes.</p><p class="subtle">O saldo pendente será retirado desta lista. Quantidades já liberadas não são alteradas.</p>${field('Motivo do cancelamento','motivo','','text','required')}`,async d=>{await api('/recebimentos/'+id,'DELETE',{motivo:d.motivo,versao:l.versao,operacao_id:operationId});S.selected.delete(id);await loadArea('awaiting');toast('Saldo em conferência cancelado.');},'Confirmar cancelamento');}

function renderExternal(){const rows=(S.external||[]).filter(l=>norm([l.material,l.lote].join(' ')).includes(norm(S.q)));$('#content').innerHTML=`<div class="toolbar"><input id="localSearch" type="search" placeholder="Pesquisar item externo" value="${esc(S.q)}" aria-label="Pesquisar externos"><button class="button" data-action="new-external">${icon('plus')} Cadastrar externo</button></div>${panel('Estoque externo',S.external===null?unavailable('external'):table(['Material / medicamento','Lote','Validade','Saldo','Situação',''],rows.map(l=>[esc(l.material),esc(l.lote),esc(l.validade||'—'),fmt(l.estoque_atual),validityBadge(l.validade),`<button class="button secondary small" data-delete-external="${l.id}">Excluir</button>`])))}`;}
function renderConference(){const rows=S.conferences||[];$('#content').innerHTML=`<div class="toolbar"><span class="subtle">Registre P/G, Nome de Guerra e a quantidade física encontrada.</span><button class="button secondary" data-action="conference-history">Histórico e relatório</button></div>${panel('Lotes selecionados para esta semana',S.conferences===null?unavailable('conferences'):table(['Produto','Lote','Estoque no sistema','Estoque físico','Resultado','Responsável',''],rows.map(c=>[esc(c.medicamento),esc(c.ficha),fmt(c.estoque_virtual),c.estoque_fisico===null?'—':fmt(c.estoque_fisico),statusBadge(c.resultado),esc([c.pg,c.nome_guerra].filter(Boolean).join(' ')||'—'),`<button class="button secondary small" data-conference="${c.id}">${c.resultado==='PENDENTE'?'Conferir':'Ver / corrigir'}</button>`])))}`;}
function renderAudit(){const rows=(S.audit||[]).filter(r=>norm(Object.values(r).join(' ')).includes(norm(S.q)));$('#content').innerHTML=`<div class="toolbar"><input id="localSearch" type="search" value="${esc(S.q)}" placeholder="Pesquisar usuário, ação ou detalhes" aria-label="Pesquisar auditoria"><button class="button secondary" data-action="print-current">${icon('print')} Imprimir</button></div>${panel('Registro de auditoria · até 1.000 ações recentes',S.audit===null?unavailable('audit'):table(['Data','Usuário','Ação','Registro','Detalhes'],rows.map(r=>[esc(r.data),esc(r.usuario),esc(r.acao),esc(r.entidade)+(r.entidade_id?' #'+esc(r.entidade_id):''),esc(r.detalhes)])))}`;}
function renderUsers(){const rows=S.users||[];$('#content').innerHTML=`<div class="toolbar"><button class="button" data-action="new-user">${icon('plus')} Novo administrador</button></div>${panel('Contas de acesso',S.users===null?unavailable('users'):table(['Usuário','Nome','Perfil','Situação','Último acesso',''],rows.map(u=>[esc(u.usuario),esc(u.nome),esc(u.perfil),badge(u.ativo?'Ativo':'Inativo',u.ativo?'success':'neutral'),esc(u.ultimo_acesso||'—'),u.perfil==='gerente'?'—':`<button class="button secondary small" data-user-toggle="${u.id}">${u.ativo?'Desativar':'Ativar'}</button>`])))}`;}
function reportRows(){const start=S.reportFrom?dateValue(S.reportFrom):null,end=S.reportTo?dateValue(S.reportTo):null;if(end)end.setHours(23,59,59,999);return(S.moves||[]).filter(m=>{const d=dateValue(m.data);return(!start||(d&&d>=start))&&(!end||(d&&d<=end))&&norm([m.medicamento,m.ficha,m.solicitante].join(' ')).includes(norm(S.q))})}
function renderReports(){const rows=reportRows();$('#content').innerHTML=`<div class="toolbar"><input id="localSearch" type="search" value="${esc(S.q)}" placeholder="Produto, ficha ou solicitante" aria-label="Pesquisar movimentações"><label class="field">De<input id="reportFrom" type="date" value="${S.reportFrom}"></label><label class="field">Até<input id="reportTo" type="date" value="${S.reportTo}"></label><button class="button secondary" data-action="print-current">${icon('print')} Imprimir / PDF</button></div>${panel(`${rows.length} movimentações`,S.moves===null?unavailable('moves'):table(['Data','Produto','Ficha','Responsável','Variação','Anterior','Final'],rows.map(m=>{const d=movementDelta(m);return[esc(m.data),esc(m.medicamento),esc(m.ficha),esc(m.solicitante),`<b class="${d>=0?'success-text':'danger-text'}">${d>0?'+':''}${fmt(d)}</b>`,fmt(m.estoque_anterior),fmt(m.estoque_final)]})))}`;}
function renderSettings(){ $('#content').innerHTML=`<div class="stack settings"><section class="panel"><h2>Servidor da farmácia</h2><p class="subtle" style="margin:10px 0 20px">Use o endereço do servidor na rede da organização. A alteração será usada também pela versão clássica.</p><form id="settingsForm"><label class="field">Endereço e porta<input name="servidor_url" value="${esc(S.config?.servidor_url||'')}" required placeholder="10.56.121.242:5000"></label><div id="settingsError" class="error-text"></div><div class="actions"><button type="button" class="button secondary" data-action="ping">Testar conexão</button><button class="button">Salvar endereço</button></div></form></section><section class="panel"><h2>Aplicativo</h2><p class="subtle" style="margin:12px 0">SISTFARMA ${boot.version} · ${client?'Cliente':'Gestor'} Farmácia<br>Todos os recursos visuais são carregados neste computador. As consultas e alterações usam o servidor configurado.</p><div class="actions">${S.user?'<button class="button secondary" data-action="change-password">Alterar minha senha</button><button class="button secondary" data-action="backup">Criar backup no servidor</button>':''}<button class="button secondary" data-action="classic">Abrir versão clássica</button></div></section></div>`;$('#settingsForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button[type=submit]')||e.target.querySelector('button:last-child');b.disabled=true;try{const cfg=await api('/config','POST',Object.fromEntries(new FormData(e.target)));clearData();S.config=cfg;S.user=null;S.cart=[];S.lastReceipt=null;toast('Endereço salvo.');await ping();render()}catch(err){$('#settingsError').textContent=err.message}finally{b.disabled=false}};}
function renderCatalog(){const items=aggregateLots(S.lots||[]),filtered=items.filter(x=>(!S.category||x.categoria===S.category)&&norm([x.medicamento,x.categoria,...x.lotes.map(l=>l.ficha)].join(' ')).includes(norm(S.q)));$('#content').innerHTML=`<div class="toolbar"><input id="localSearch" type="search" aria-label="Pesquisar catálogo" placeholder="Digite o nome do medicamento ou material" value="${esc(S.q)}">${categorySelect()}<button class="button secondary" data-action="refresh">Atualizar catálogo</button></div><div class="split"><div>${S.lots===null?panel('Catálogo',unavailable('lots')):`<div class="stats-line"><b>${filtered.length} produtos encontrados</b><span>Quantidades em unidades, não em cartelas.</span></div><div class="catalog">${filtered.slice(0,100).map(x=>{const idx=items.indexOf(x),dates=x.lotes.filter(l=>number(l.estoque_atual)>0&&dateValue(l.validade)).sort((a,b)=>dateValue(a.validade)-dateValue(b.validade));return `<article class="product"><small>${esc(x.categoria)}</small><h3>${esc(x.medicamento)}</h3><small>Cartela: ${x.comprimidos_por_cartela.length?x.comprimidos_por_cartela.map(fmt).join(' / ')+' unidades':'não informada'}</small><small>Validade mais próxima: ${esc(dates[0]?.validade||'não informada')}</small><div class="product-bottom"><span><strong>${fmt(x.estoque_total)}</strong> <small>disponíveis</small></span><button class="button small" data-add-product="${idx}" ${x.estoque_total<=0?'disabled':''}>Adicionar</button></div></article>`}).join('')||empty()}</div>${filtered.length>100?'<div class="notice">Exibindo os primeiros 100 produtos. Refine sua pesquisa.</div>':''}`}</div><section class="panel cart-panel"><div class="panel-heading"><h2>Sua solicitação</h2>${badge(S.cart.length+' itens','success')}</div>${S.cart.map((x,i)=>`<div class="cart-row"><strong>${esc(x.medicamento)}</strong><div class="cart-controls"><label class="subtle">Unidades <input type="number" min="0.01" step="any" value="${x.quantidade_retirada}" data-cart-qty="${i}" aria-label="Quantidade de ${esc(x.medicamento)}"></label><button class="text-button danger-text" data-remove-cart="${i}">Remover</button></div></div>`).join('')||empty('Adicione produtos para montar o pedido.')}<form id="requestForm"><label class="field">P/G<input name="pg" required value="${esc(S.requestDraft?.pg||'')}" placeholder="Ex.: Cb"></label><label class="field">Nome de Guerra<input name="solicitante" required value="${esc(S.requestDraft?.solicitante||'')}" autocomplete="name"></label><label class="field">OM<input name="om" required value="${esc(S.requestDraft?.om||'')}" placeholder="Organização Militar"></label><div id="requestError" class="error-text" role="alert"></div><button class="button" ${!S.cart.length||S.lots===null?'disabled':''}>Enviar solicitação ${icon('arrow')}</button><p class="subtle">A disponibilidade é conferida pelo servidor no envio.</p></form></section></div>`;$('#requestForm').onsubmit=async e=>{e.preventDefault();if(S.uncertainRequest&&!window.confirm('Você já verificou com a farmácia que o pedido anterior não foi registrado?'))return;const body={...Object.fromEntries(new FormData(e.target)),itens:S.cart.map(({categoria,medicamento,quantidade_retirada})=>({categoria,medicamento,quantidade_retirada}))};if(!body.itens.length||body.itens.some(x=>!Number.isFinite(+x.quantidade_retirada)||+x.quantidade_retirada<=0)){ $('#requestError').textContent='Informe quantidades maiores que zero.';return}const b=e.target.querySelector('button');b.disabled=true;try{const receipt=await api('/retiradas','POST',body);S.lastReceipt={...receipt,pg:body.pg,om:body.om,solicitante:body.solicitante,data:new Date().toLocaleString('pt-BR')};S.cart=[];S.requestDraft={};S.uncertainRequest=false;navigate('receipt');toast('Resposta do pedido recebida. Confira os itens atendidos e cancelados.');await refresh()}catch(err){$('#requestError').textContent=err.message;if(err.uncertain){S.uncertainRequest=true;$('#requestError').insertAdjacentHTML('beforeend','<br>Consulte o Gestor Farmácia antes de enviar novamente.');b.textContent='Conferi: enviar novamente';b.disabled=false;return}b.disabled=false}};}
function receiptHtml(r){if(!r)return empty('Nenhuma solicitação foi enviada nesta sessão.');const rows=[];for(const item of r.itens||[])rows.push([esc(item.medicamento),(item.movimentos||[]).map(x=>esc(x.ficha)).join(', '),fmt((item.movimentos||[]).reduce((a,m)=>a+number(m.retirada),0)),badge('Atendido','success')]);for(const item of r.itens_cancelados||[])rows.push([esc(item.medicamento)+'<span class="secondary">'+esc(item.motivo)+'</span>','—',fmt(item.quantidade),badge('Cancelado: sem estoque','danger')]);return `<p class="subtle">Pedido <b>#${esc(r.pedido_id)}</b> · ${esc(r.data||'')}<br>${esc(r.pg)} ${esc(r.solicitante)} · ${esc(r.om)}</p>${(r.avisos||[]).map(a=>`<div class="notice error">${esc(a)}</div>`).join('')}${table(['Produto','Ficha / lote','Quantidade','Resultado'],rows)}`;}
function renderReceipt(){ $('#content').innerHTML=panel('Resultado da solicitação',receiptHtml(S.lastReceipt),S.lastReceipt?'<button class="button secondary" data-action="print-receipt">Imprimir / PDF</button>':'');}
function openDialog(title,html){$('#dialogTitle').textContent=title;$('#dialogContent').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal();}
function formDialog(title,html,onSubmit,label='Salvar'){openDialog(title,`<form id="modalForm">${html}<div class="error-text" id="modalError" role="alert"></div><div class="actions"><button class="button secondary" type="button" data-action="close-dialog">Cancelar</button><button class="button" type="submit">${label}</button></div></form>`);$('#modalForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('[type=submit]');b.disabled=true;$('#modalError').textContent='';try{await onSubmit(Object.fromEntries(new FormData(e.target)));$('#dialog').close()}catch(err){$('#modalError').textContent=err.message}finally{b.disabled=false}};}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function isoDate(v){const d=dateValue(v);return d?`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`:'';}
function brDate(v){const d=dateValue(v);return d?d.toLocaleDateString('pt-BR'):'';}
function numeric(v,label){const n=Number(v);if(v===''||!Number.isFinite(n)||n<0)throw Error(label+' deve ser um número igual ou maior que zero.');return n;}
function lotForm(id){const operationId=crypto.randomUUID();const lot=id?(S.lots||[]).find(l=>l.id===+id):null;const category=lot?.categoria||(S.area==='controlled'?'Medicamentos Controlados':S.category)||CATEGORIES[0];formDialog(lot?'Editar lote':'Cadastrar lote',`<div class="form-grid"><label class="field wide">Categoria<select name="categoria" ${lot?'disabled':''}>${CATEGORIES.map(c=>`<option ${c===category?'selected':''}>${esc(c)}</option>`).join('')}</select></label>${field('Medicamento / material','medicamento',lot?.medicamento||'','text','required')}${field('Ficha / lote','ficha',lot?.ficha||'','text','required')}${field('Localizador','localizador',lot?.localizador||'','text','maxlength="120" placeholder="Ex.: Depósito A · Prateleira 03"')}${field('Validade','validade',isoDate(lot?.validade),'date')}${field('Estoque inicial','estoque_inicial',lot?.estoque_inicial??0,'number','required min="0" step="any"')}${lot?field('Estoque atual','estoque_atual',lot.estoque_atual,'number','required min="0" step="any"'):''}${field('Comprimidos por cartela','comprimidos_cartela',lot?.comprimidos_cartela||'','number','min="1" step="1"')}</div>${!lot?`<label class="check"><input type="checkbox" name="aguardando_conferencia" id="awaitingCheckbox" ${S.area==='awaiting'?'checked':''}> Colocar produto em conferência / SISCOFIS</label><p class="subtle">Marcado: saldo separado, indisponível para pedidos até a liberação.</p><label class="field" id="awaitingNotes" ${S.area==='awaiting'?'':'hidden'}>Observação da conferência<textarea name="observacao" placeholder="Documento, recebimento ou pendência"></textarea></label>`:''}${lot?`<div class="actions"><button class="button secondary small" type="button" data-transfer="${lot.id}">Mover para Controlados / Externos</button><button class="button danger small" type="button" data-delete-lot="${lot.id}">Excluir lote</button></div>`:''}`,async d=>{let body;if(lot){body={lote_id:lot.id,categoria:lot.categoria,medicamento:d.medicamento.trim(),ficha:d.ficha.trim(),validade:brDate(d.validade),estoque_inicial:numeric(d.estoque_inicial,'Estoque inicial'),estoque_atual:numeric(d.estoque_atual,'Estoque atual'),comprimidos_cartela:d.comprimidos_cartela||'',localizador:d.localizador||''}}else{body={categoria:d.categoria,medicamento:d.medicamento.trim(),ficha:d.ficha.trim(),validade:brDate(d.validade),estoque_inicial:numeric(d.estoque_inicial,'Estoque inicial'),comprimidos_cartela:d.comprimidos_cartela||'',localizador:d.localizador||''}}if(!d.medicamento.trim()||!d.ficha.trim())throw Error('Preencha o produto e a ficha.');if(!lot&&d.aguardando_conferencia){if(body.estoque_inicial<=0)throw Error('Informe a quantidade recebida, maior que zero.');await api('/recebimentos','POST',{...body,observacao:d.observacao||'',operacao_id:operationId});toast('Produto registrado em conferência, indisponível para uso.');S.area='awaiting';S.selected.clear();}else{await api('/itens-localizados',lot?'PUT':'POST',{...body,operacao_id:operationId});toast('Lote e localizador salvos no estoque disponível.');}await refresh()});}
function transferForm(id){const lot=S.lots.find(l=>l.id===+id);formDialog('Transferir estoque',`<p class="subtle" style="margin-bottom:18px">${esc(lot.medicamento)} · Ficha ${esc(lot.ficha)} · Saldo ${fmt(lot.estoque_atual)}</p><div class="form-grid"><label class="field">Destino<select name="destino"><option value="controlados">Medicamentos Controlados</option><option value="externos">Externos</option></select></label>${field('Quantidade a mover','quantidade',lot.estoque_atual,'number','required min="0.01" step="any"')}<label class="check wide"><input type="checkbox" name="mover_tudo"> Mover todo o estoque disponível no servidor</label></div>`,async d=>{const qtd=numeric(d.quantidade,'Quantidade');if(!d.mover_tudo&&qtd<=0)throw Error('Informe uma quantidade maior que zero.');await api('/estoque/transferir','POST',{lote_id:lot.id,destino:d.destino,quantidade:qtd,mover_tudo:!!d.mover_tudo});toast('Estoque transferido.');await refresh()},'Transferir');}
function deleteLots(ids){const lots=S.lots.filter(l=>ids.includes(l.id));formDialog('Excluir '+lots.length+' lote(s)',`<p class="subtle" style="margin-bottom:16px">Os lotes serão removidos do estoque ativo. A exclusão fica registrada no servidor.</p>${table(['Produto','Ficha','Saldo'],lots.map(l=>[esc(l.medicamento),esc(l.ficha),fmt(l.estoque_atual)]))}<div style="margin-top:18px">${field('Motivo','motivo','','text','required')}</div>`,async d=>{const done=[];try{for(const l of lots){await api('/itens','DELETE',{lote_id:l.id,categoria:l.categoria,medicamento:l.medicamento,ficha:l.ficha,validade:l.validade||'',motivo:d.motivo});done.push(l.id);S.selected.delete(l.id)}}catch(err){await refresh();throw Error(`${done.length} de ${lots.length} lotes excluídos. `+err.message)}await refresh();toast(`${done.length} lote(s) excluído(s).`)},'Confirmar exclusão');}
async function orderDialog(id){try{
 const d=await api('/pedidos/'+id),p=d.pedido;let locationByItem=new Map(),warning='';
 try{const detail=await api('/pedidos/'+id+'/localizadores');locationByItem=new Map(detail.itens.map(item=>[item.item_id,item.localizadores||[]]))}catch(err){warning=err.message}
 const localHtml=i=>{const places=locationByItem.get(i.id)||[];return places.length?places.map(loc=>`<div><strong>${esc(loc.localizador||'Não informado')}</strong><span class="secondary">Ficha ${esc(loc.ficha||'—')} · ${fmt(loc.quantidade)} unidades</span></div>`).join(''):i.status==='CANCELADO_SEM_ESTOQUE'?'—':'Não informado'};
 openDialog('Pedido #'+id,`<p class="subtle" style="margin-bottom:18px">${esc(p.data)} · ${esc(p.pg)} ${esc(p.solicitante||p.nome)}<br>OM: ${esc(p.om)} · ${statusBadge(p.status)}</p>${warning?`<div class="notice error">Localizadores indisponíveis: ${esc(warning)}</div>`:''}${table(['Item','Quantidade','Fichas','Localizador do lote','Situação'],(p.itens||[]).map(i=>[esc(i.medicamento)+(i.motivo?`<span class="secondary">${esc(i.motivo)}</span>`:''),fmt(i.quantidade),esc(i.fichas||i.ficha||'—'),localHtml(i),statusBadge(i.status)]))}<div class="actions"><button class="button secondary" data-action="print-dialog">Imprimir / PDF</button>${!['ENTREGUE','CANCELADO'].includes(p.status)?`<select id="nextStatus" aria-label="Nova situação"><option value="EM_SEPARACAO">Em separação</option><option value="PRONTO">Pronto</option><option value="ENTREGUE">Entregue</option><option value="CANCELADO">Cancelar e estornar</option></select><button class="button" data-update-order="${p.id}">Atualizar situação</button>`:''}</div>`)}catch(err){toast(err.message,true)}}
function conferenceForm(id){const c=S.conferences.find(c=>c.id===+id);formDialog('Conferir lote',`<p class="subtle" style="margin-bottom:18px">${esc(c.medicamento)} · Ficha ${esc(c.ficha)}<br>Saldo registrado: ${fmt(c.estoque_virtual)}. Informe a contagem física.</p><div class="form-grid">${field('P/G','pg',c.pg||'','text','required')}${field('Nome de Guerra','nome_guerra',c.nome_guerra||'','text','required')}${field('Quantidade física','estoque_fisico',c.estoque_fisico??c.estoque_virtual,'number','required min="0" step="any"')}<label class="field">Ação<select name="ajustar"><option value="false">Registrar conferência / Lote OK</option><option value="true">Alterar lote para a contagem física</option></select></label><label class="field wide">Observação<textarea name="observacao">${esc(c.observacao||'')}</textarea></label></div>`,async d=>{await api('/conferencias/'+id,'POST',{...d,estoque_fisico:numeric(d.estoque_fisico,'Estoque físico'),ajustar:d.ajustar==='true'});toast('Conferência registrada.');await refresh()});}
function externalForm(){formDialog('Cadastrar externo',`<div class="form-grid">${field('Material / medicamento','material','','text','required')}${field('Lote','lote','','text','required')}${field('Validade','validade','','date')}${field('Quantidade inicial','estoque_inicial',0,'number','required min="0" step="any"')}<label class="field wide">Observação<textarea name="observacao"></textarea></label></div>`,async d=>{await api('/apoio','POST',{...d,validade:brDate(d.validade),estoque_inicial:numeric(d.estoque_inicial,'Estoque')});toast('Item externo cadastrado.');await loadArea('external')});}
function newUser(){formDialog('Novo administrador',`<div class="form-grid">${field('Nome','nome','','text','required')}${field('Usuário','usuario','','text','required autocomplete="off"')}${field('Senha inicial','senha','','password','required minlength="6" autocomplete="new-password"')}<p class="subtle">Perfil Administrador. A auditoria e a gestão de usuários permanecem exclusivas do Gerente.</p></div>`,async d=>{await api('/usuarios','POST',{...d,perfil:'administrador'});toast('Administrador criado.');await loadArea('users')});}
function changePassword(){formDialog('Alterar minha senha',`<div class="form-grid">${field('Nova senha','nova_senha','','password','required minlength="6" autocomplete="new-password"')}${field('Confirmar senha','confirmacao','','password','required minlength="6" autocomplete="new-password"')}</div>`,async d=>{if(d.nova_senha!==d.confirmacao)throw Error('As senhas são diferentes.');await api('/minha-senha','POST',{nova_senha:d.nova_senha});toast('Senha alterada.')});}
function printHtml(title,html){$('#printArea').innerHTML=`<h1>SISTFARMA · ${esc(title)}</h1><p>Emitido em ${esc(new Date().toLocaleString('pt-BR'))}</p>${html}`;window.print()}
function preserveRender(){const el=document.activeElement,id=el?.id,start=el?.selectionStart,end=el?.selectionEnd;render();if(id){const next=document.getElementById(id);if(next){next.focus();if(start!==null&&start!==undefined&&typeof next.setSelectionRange==='function')try{next.setSelectionRange(start,end)}catch(_){}}}}
let searchTimer;
document.addEventListener('input',e=>{const el=e.target;if(el.id==='localSearch'||el.id==='globalSearch'){S.q=el.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(el.id==='globalSearch'&&!['stock','controlled','validities','catalog','awaiting'].includes(S.area)){S.area=client?'catalog':'stock';S.filter='all';S.category=''}preserveRender()},140)}if(el.matches('[data-cart-qty]'))S.cart[+el.dataset.cartQty].quantidade_retirada=el.value;if(el.closest('#requestForm')){S.requestDraft=Object.fromEntries(new FormData($('#requestForm')))}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='awaitingCheckbox')$('#awaitingNotes').hidden=!el.checked;if(el.matches('[data-select-awaiting]')){el.checked?S.selected.add(+el.dataset.selectAwaiting):S.selected.delete(+el.dataset.selectAwaiting);render()}if(el.id==='selectAllAwaiting'){currentAwaiting().forEach(l=>el.checked?S.selected.add(l.id):S.selected.delete(l.id));render()}if(el.id==='categoryFilter'){S.category=el.value;S.selected.clear();render()}if(el.id==='stockFilter'){S.filter=el.value;S.selected.clear();render()}if(el.id==='orderFilter'){S.orderFilter=el.value;render()}if(el.id==='reportFrom'){S.reportFrom=el.value;render()}if(el.id==='reportTo'){S.reportTo=el.value;render()}if(el.matches('[data-select-lot]')){el.checked?S.selected.add(+el.dataset.selectLot):S.selected.delete(+el.dataset.selectLot);render()}if(el.id==='selectAll'){currentLots().forEach(l=>el.checked?S.selected.add(l.id):S.selected.delete(l.id));render()}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;try{
 if(d.editAwaiting){awaitingForm(+d.editAwaiting);return}if(d.releaseAwaiting){releaseAwaiting([+d.releaseAwaiting]);return}if(d.cancelAwaiting){cancelAwaiting(+d.cancelAwaiting);return}if(d.nav){navigate(d.nav,d.filter);return}if(d.find){navigate(client?'catalog':'stock');S.q=d.find;S.filter='all';render();return}if(d.lot){lotForm(d.lot);return}if(d.transfer){transferForm(d.transfer);return}if(d.deleteLot){deleteLots([+d.deleteLot]);return}if(d.order){await orderDialog(d.order);return}if(d.conference){conferenceForm(d.conference);return}
 if(d.addProduct!==undefined){const p=aggregateLots(S.lots)[+d.addProduct],existing=S.cart.find(c=>c.categoria===p.categoria&&c.medicamento===p.medicamento);if(existing)existing.quantidade_retirada=number(existing.quantidade_retirada)+1;else S.cart.push({categoria:p.categoria,medicamento:p.medicamento,quantidade_retirada:1});render();return}if(d.removeCart!==undefined){S.cart.splice(+d.removeCart,1);render();return}
 if(d.updateOrder){const status=$('#nextStatus').value;if(status==='CANCELADO'&&!window.confirm('Cancelar este pedido e devolver ao estoque os itens atendidos?'))return;b.disabled=true;try{await api('/pedidos/'+d.updateOrder+'/status','POST',{status});$('#dialog').close();toast('Situação atualizada.');await refresh()}finally{b.disabled=false}return}
 if(d.deleteExternal){const item=S.external.find(x=>x.id===+d.deleteExternal);formDialog('Excluir item externo',`<p>Excluir ${esc(item.material)} · lote ${esc(item.lote)}?</p>`,async()=>{await api('/apoio','DELETE',{material:item.material,lote:item.lote});await loadArea('external');toast('Item excluído.')},'Confirmar exclusão');return}
 if(d.userToggle){const u=S.users.find(x=>x.id===+d.userToggle);formDialog(u.ativo?'Desativar usuário':'Ativar usuário',`<p>${u.ativo?'Desativar':'Ativar'} o acesso de ${esc(u.nome)} (${esc(u.usuario)})?</p>`,async()=>{await api('/usuarios/'+u.id+'/ativo','POST',{ativo:!u.ativo});await loadArea('users')},'Confirmar');return}
 const action=d.action;if(action==='release-selected')releaseAwaiting([...S.selected]);if(action==='awaiting-history'){const rows=await fetchResource('awaiting','/recebimentos/historico','liberacoes');openDialog('Histórico de liberações SISCOFIS',table(['Data','Produto / lote','Quantidade liberada','Responsável','Referência'],rows.map(r=>[esc(r.data),esc(r.medicamento)+'<span class="secondary">'+esc(r.ficha)+'</span>',fmt(r.quantidade),esc(r.usuario),esc(r.referencia||'—')]))+'<p class="subtle">Últimas 2.000 liberações. Edições e cancelamentos constam na Auditoria.</p><div class="actions"><button class="button secondary" data-action="print-dialog">Imprimir / PDF</button></div>')}if(action==='refresh')await refresh();if(action==='new-lot')lotForm();if(action==='delete-selected')deleteLots([...S.selected]);if(action==='new-external')externalForm();if(action==='new-user')newUser();if(action==='change-password')changePassword();if(action==='close-dialog')$('#dialog').close();
 if(action==='ping'){await ping();toast(S.connected?'Conexão com o servidor confirmada.':'Não foi possível conectar ao servidor.',!S.connected)}
 if(action==='classic'){await api('/classico','POST',{});toast('Abrindo a versão clássica.')}
 if(action==='backup'){b.disabled=true;try{const r=await api('/backup','POST',{});toast('Backup criado no servidor: '+(r.arquivo||''))}finally{b.disabled=false}}
 if(action==='conference-history'){const rows=await fetchResource('conferenceHistory','/conferencias/historico','conferencias');openDialog('Histórico de conferências',table(['Data','Produto','Responsável','Físico','Diferença','Resultado'],rows.map(c=>[esc(c.conferido_em),esc(c.medicamento),esc([c.pg,c.nome_guerra].join(' ')),fmt(c.estoque_fisico),fmt(c.diferenca),statusBadge(c.resultado)]))+'<div class="actions"><button class="button secondary" data-action="print-dialog">Imprimir / PDF</button></div>')}
 if(action==='deleted-lots'){const rows=await fetchResource('deleted','/lotes-excluidos','lotes');openDialog('Lotes excluídos',table(['Data','Produto','Ficha','Responsável','Motivo'],rows.map(l=>[esc(l.excluido_em),esc(l.medicamento),esc(l.ficha),esc(l.excluido_por),esc(l.motivo)])))}
 if(action==='print-stock')printHtml(titles[S.area][0],table(['Produto','Categoria','Ficha','Localizador','Validade','Saldo','Cartela'],currentLots().map(l=>[esc(l.medicamento),esc(l.categoria),esc(l.ficha),esc(l.localizador||'—'),esc(l.validade||'—'),fmt(l.estoque_atual),esc(l.comprimidos_cartela||'—')])));
 if(action==='print-current')printHtml(titles[S.area][0],'<p>'+esc(S.q)+(S.reportFrom?' · De '+brDate(S.reportFrom):'')+(S.reportTo?' até '+brDate(S.reportTo):'')+'</p>'+($('#content table')?.outerHTML||empty()));
 if(action==='print-dialog')printHtml($('#dialogTitle').textContent,$('#dialogContent').innerHTML.replace(/<div class="actions">[\s\S]*<\/div>$/,''));if(action==='print-receipt')printHtml('Comprovante do pedido',receiptHtml(S.lastReceipt));
 }catch(err){toast(err.message,true);if(!S.user&&!client)render()}});
$('#menuToggle').innerHTML=icon('menu');$('#searchIcon').innerHTML=icon('search');$('#refreshTop').innerHTML=icon('refresh');$('#menuToggle').onclick=()=>{document.body.classList.toggle('sidebar-hidden');$('#menuToggle').setAttribute('aria-expanded',String(!document.body.classList.contains('sidebar-hidden')))};$('#refreshTop').onclick=refresh;$('#closeDialog').onclick=()=>$('#dialog').close();$('#logout').onclick=async()=>{await api('/logout','POST',{});S.user=null;clearData();S.area='dashboard';render()};
function tick(){const now=new Date();$('#clock').textContent=now.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});$('#today').textContent=now.toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric'});}tick();setInterval(tick,30000);
setInterval(()=>api('/heartbeat','POST',{}).catch(()=>{}),20000);
async function start(){try{S.config=await api('/config');S.user=S.config.usuario;render();await refresh()}catch(err){$('#content').innerHTML=empty(err.message);connection(false)}}
start();
